@register.simple_tag()
def render_cms_structure_js(renderer, obj):
    cms_page = obj.page
    markup_bits = []
    page_placeholders_by_slot = obj.rescan_placeholders()
    for placeholder_node in cms_page.get_declared_placeholders():
        page_placeholder = page_placeholders_by_slot.get(placeholder_node.slot)
        if page_placeholder:
            placeholder_js = renderer.render_page_placeholder(cms_page, page_placeholder)
            markup_bits.append(placeholder_js)
    return mark_safe('\n'.join(markup_bits))

def render_object_edit(request, content_type_id, object_id):
    content_type = ContentType.objects.get_for_id(content_type_id)

    if not is_editable_model(content_type.model_class()):
        raise Http404

    try:
        content_type_obj = content_type.get_object_for_this_type(pk=object_id)
    except ObjectDoesNotExist:
        raise Http404

    if not hasattr(content_type_obj, 'get_absolute_url'):
        return HttpResponseBadRequest('Requested object does not have a valid url')

    abs_url = content_type_obj.get_absolute_url()
    match = resolve(abs_url)
    toolbar = get_toolbar_from_request(request)
    toolbar.set_object(content_type_obj)
    return match.func(request, **match.kwargs)

